impl From<String> for StartingElement {
    fn from(text: String) -> Self {
        match Self::value_of(&text) {
            Some(member) if officekit_markup_base::spells(&member, &text) => Self::Member(member),
            Some(_) | None => Self::Spelled(text.into_boxed_str()),
        }
    }
}

impl From<StartingElementMember> for StartingElement {
    fn from(member: StartingElementMember) -> Self {
        Self::Member(member)
    }
}

impl Spelling for StartingElement {
    fn spelling(&self, _class: ConformanceClass) -> Cow<'_, str> {
        match self {
            Self::Member(member) => Cow::Borrowed(member.as_str()),
            Self::Spelled(text) => Cow::Borrowed(text),
        }
    }
}

impl fmt::Display for StartingElementMember {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(self.as_str())
    }
}

impl StartingElementMember {
    const MEMBERS: &officekit_markup_base::Members<Self> =
        &[(Self::Node, "node", None), (Self::Trans, "trans", None)];

    /// The text the member stands for.
    #[must_use = "this only returns the text of the member"]
    pub fn as_str(self) -> &'static str {
        officekit_markup_base::member_text(Self::MEMBERS, self)
    }

    /// The Office version that brought the member, from the data of the Open XML SDK, version 3.5.1; `None` for
    /// ECMA-376's own.
    #[must_use = "this only returns the Office version of the member"]
    pub fn introduced(self) -> Option<OfficeVersion> {
        officekit_markup_base::member_version(Self::MEMBERS, self)
    }
}

impl StartingElement {
    /// The value `text` spells.
    ///
    /// # Errors
    ///
    /// `ValueError` when `text` is no value of `ST_StartingElement`.
    pub fn parse(text: &str) -> Result<StartingElementMember, ValueError> {
        Self::value_of(text)
            .ok_or_else(|| officekit_markup_base::invalid(text, "ST_StartingElement"))
    }

    /// The member the value keeps, or the one its spelling spells.
    ///
    /// # Errors
    ///
    /// `ValueError` when a kept spelling is no value of `ST_StartingElement`.
    pub fn value(&self) -> Result<StartingElementMember, ValueError> {
        match self {
            Self::Member(member) => Ok(*member),
            Self::Spelled(text) => Self::parse(text),
        }
    }

    /// The value `text` spells; `None` when it spells none.
    #[must_use = "this only returns the value"]
    pub fn value_of(text: &str) -> Option<StartingElementMember> {
        officekit_markup_base::member(StartingElementMember::MEMBERS, text)
    }
}

